import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import * as request from 'supertest';
import { AppModule } from '../src/app.module';
import { DataSource } from 'typeorm';

describe('DepositController (integration)', () => {
  let app: INestApplication;
  let jwtToken: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    await app.init();

    // Login pour obtenir un token JWT
    const loginResponse = await request(app.getHttpServer())
      .post('/auth/login')
      .send({ email: 'test@example.com', password: 'password123' });
    jwtToken = loginResponse.body.accessToken;
  });

  afterAll(async () => {
    await app.get(DataSource).dropDatabase();
    await app.close();
  });

  it('should initiate a deposit successfully', async () => {
    const depositDto = {
      amount: 10000,
      phoneNumber: '+237699999999',
      paymentMethod: 'ORANGE_MONEY'
    };

    const response = await request(app.getHttpServer())
      .post('/deposits/initiate')
      .set('Authorization', `Bearer ${jwtToken}`)
      .send(depositDto)
      .expect(201);

    expect(response.body).toHaveProperty('message', 'Demande de dépôt initiée.');
    expect(response.body).toHaveProperty('depositId');
    expect(response.body).toHaveProperty('reference');
    expect(response.body.depositId).toMatch(/^[0-9a-f-]{36}$/); // UUID
  });

  it('should return 401 when no token is provided', async () => {
    await request(app.getHttpServer())
      .post('/deposits/initiate')
      .send({ amount: 10000, phoneNumber: '+237699999999' })
      .expect(401);
  });
});
