import { DataSource } from 'typeorm';
import { User } from '../src/database/entities/user.entity';
import { Wallet } from '../src/database/entities/wallet.entity';
import { Product } from '../src/database/entities/product.entity';
import { Category } from '../src/database/entities/category.entity';
import * as bcrypt from 'bcrypt';

export class TestDataSeeder {
  constructor(private dataSource: DataSource) {}

  async seed(): Promise<void> {
    await this.clearData();
    await this.seedUsers();
    await this.seedCategories();
    await this.seedProducts();
  }

  private async clearData(): Promise<void> {
    await this.dataSource.query('TRUNCATE TABLE "transaction" CASCADE;');
    await this.dataSource.query('TRUNCATE TABLE product CASCADE;');
    await this.dataSource.query('TRUNCATE TABLE category CASCADE;');
    await this.dataSource.query('TRUNCATE TABLE wallet CASCADE;');
    await this.dataSource.query('TRUNCATE TABLE "user" CASCADE;');
  }

  private async seedUsers(): Promise<void> {
    const userRepo = this.dataSource.getRepository(User);
    const walletRepo = this.dataSource.getRepository(Wallet);

    const users = [
      { email: 'admin@sawamart.com', password: 'admin123', role: 'admin' },
      { email: 'seller1@sawamart.com', password: 'seller123', role: 'seller' },
      { email: 'seller2@sawamart.com', password: 'seller123', role: 'seller' },
      { email: 'buyer1@example.com', password: 'buyer123', role: 'buyer' },
      { email: 'buyer2@example.com', password: 'buyer123', role: 'buyer' },
    ];

    for (const userData of users) {
      const user = userRepo.create({
        ...userData,
        password: await bcrypt.hash(userData.password, 10),
        isActive: true,
        createdAt: new Date(),
      });
      await userRepo.save(user);

      // Créer un wallet pour chaque utilisateur
      const wallet = walletRepo.create({
        userId: user.id,
        balance: Math.floor(Math.random() * 50000) + 1000,
        currency: 'XAF',
      });
      await walletRepo.save(wallet);
    }
  }

  private async seedCategories(): Promise<void> {
    const categoryRepo = this.dataSource.getRepository(Category);
    const categories = [
      { name: 'Électronique', description: 'Téléphones, ordinateurs...' },
      { name: 'Mode', description: 'Vêtements, chaussures...' },
      { name: 'Maison', description: 'Meubles, décoration...' },
      { name: 'Auto', description: 'Pièces détachées, accessoires...' },
    ];
    await categoryRepo.save(categoryRepo.create(categories));
  }

  private async seedProducts(): Promise<void> {
    const productRepo = this.dataSource.getRepository(Product);
    const categoryRepo = this.dataSource.getRepository(Category);
    const categories = await categoryRepo.find();

    const products = [
      { name: 'iPhone 13', price: 850000, category: categories[0], stock: 10 },
      { name: 'Samsung Galaxy S21', price: 750000, category: categories[0], stock: 8 },
      { name: 'T-shirt Nike', price: 15000, category: categories[1], stock: 50 },
      { name: 'Canapé 3 places', price: 250000, category: categories[2], stock: 5 },
      { name: 'Pneu Michelin 17"', price: 120000, category: categories[3], stock: 20 },
    ];

    for (const productData of products) {
      const product = productRepo.create({
        ...productData,
        status: 'active',
        createdAt: new Date(),
      });
      await productRepo.save(product);
    }
  }
}
